226	/// Result of a prompt.
227	#[derive(Debug, Clone)]
228	pub enum PromptResult {
229	    /// Boolean result from confirm.
230	    Bool(bool),
231	    /// String result from input or select.
232	    String(String),
233	    /// Multiple string results from multi-select.
234	    Strings(Vec<String>),
235	}
