225	/// Create the appropriate UI based on context.
226	pub fn create_ui(interactive: bool, mode: OutputMode) -> Box<dyn UserInterface> {
227	    if interactive && Term::stdout().is_term() {
228	        Box::new(TerminalUI::new(mode))
229	    } else {
230	        Box::new(NonInteractiveUI::new(mode))
231	    }
