1	//! Process group / job control regression tests.
2	//!
3	//! These tests verify that bivvy survives running under a real
4	//! job-controlling shell (zsh with `MONITOR` option). The existing PTY
5	//! tests spawn bivvy directly — the expectrl PTY *is* the controlling
6	//! terminal, so there's no parent shell doing process group management.
7	//! That topology can't surface the bug where zsh reclaims the foreground
8	//! group after a child process exits, causing SIGTTOU/SIGTTIN or
9	//! premature suspension.
10	//!
11	//! These tests spawn **zsh** inside the PTY, then run bivvy as a
12	//! command within that zsh session. This gives us:
13	//!   - Real job control (zsh's `MONITOR` option)
14	//!   - Real process group assignment and foreground management
15	//!   - Real signal delivery (SIGTTOU, SIGTTIN, SIGTSTP)
16	//!   - A parent shell that actively manages the terminal foreground
17	//!
18	//! The critical transition under test: after a child process (step
19	//! command) exits, bivvy must reclaim the terminal foreground to
20	//! render the next interactive prompt. If process group isolation or
21	//! foreground reclamation is broken, the prompt never appears and
22	//! the test times out — or zsh reports "suspended (tty output)".
23	#![cfg(unix)]
24	
25	use assert_cmd::cargo::cargo_bin;
26	use expectrl::Session;
27	use std::fs;
28	use std::process::Command;
29	use std::time::Duration;
30	use tempfile::TempDir;
31	
32	const TIMEOUT: Duration = Duration::from_secs(60);
33	
34	/// Marker printed by .zshrc to confirm the shell is ready.
35	const READY: &str = "ZSH_READY";
36	
37	// ── ANSI stripping ──────────────────────────────────────────────────
38	
39	/// Strip ANSI escape sequences from PTY output for readable snapshots.
40	///
41	/// Handles:
42	///   - CSI sequences: `ESC [ <params> <final>`
43	///   - OSC sequences: `ESC ] ... BEL` or `ESC ] ... ESC \`
44	///   - SS2/SS3:       `ESC N <char>` / `ESC O <char>`
45	///   - Two-byte:      `ESC <letter>` (e.g. `ESC =`, `ESC >`)
46	fn strip_ansi(s: &str) -> String {
47	    let mut result = String::with_capacity(s.len());
48	    let mut chars = s.chars().peekable();
49	
50	    while let Some(c) = chars.next() {
51	        if c == '\x1b' {
52	            match chars.peek() {
53	                // CSI: ESC [ <params> <final byte 0x40-0x7E>
54	                Some('[') => {
55	                    chars.next(); // consume '['
56	                    for ch in chars.by_ref() {
57	                        if ch.is_ascii() && (0x40..=0x7E).contains(&(ch as u8)) {
58	                            break;
59	                        }
60	                    }
61	                }
62	                // OSC: ESC ] ... (BEL | ESC \)
63	                Some(']') => {
64	                    chars.next(); // consume ']'
65	                    for ch in chars.by_ref() {
66	                        if ch == '\x07' {
67	                            break;
68	                        }
69	                        if ch == '\x1b' {
70	                            if chars.peek() == Some(&'\\') {
71	                                chars.next();
72	                            }
73	                            break;
74	                        }
75	                    }
76	                }
77	                // SS2 / SS3: ESC N/O + one character
78	                Some('N') | Some('O') => {
79	                    chars.next();
80	                    chars.next();
81	                }
82	                // Two-byte sequence: ESC + anything else
83	                Some(_) => {
84	                    chars.next();
85	                }
86	                None => {}
87	            }
88	        } else if c == '\x07' {
89	            // Bare BEL — skip
90	        } else {
91	            result.push(c);
92	        }
93	    }
94	    result
95	}
96	
97	/// Normalize PTY output for stable snapshots.
98	///
99	/// Only strips ANSI codes, removes \r, and replaces timing values
100	/// with `[TIME]`. Does NOT filter content — everything bivvy produces
101	/// should be visible in the snapshot.
102	fn normalize_for_snapshot(s: &str) -> String {
103	    let stripped = strip_ansi(s);
104	    let re_time = regex::Regex::new(r"\b\d+(\.\d+)?(ms|s)\b").unwrap();
105	    // Caret-notation escape sequences echoed by PTY: ^[[B, ^[[A, etc.
106	    let re_caret_csi = regex::Regex::new(r"\^\[[\[0-9;]*[A-Za-z~]").unwrap();
107	
108	    stripped
109	        .replace('\r', "")
110	        .lines()
111	        .map(|line| {
112	            let trimmed = line.trim_end();
113	            let no_caret = re_caret_csi.replace_all(trimmed, "");
114	            re_time.replace_all(&no_caret, "[TIME]").to_string()
115	        })
116	        // Drop leading zsh prompt noise (% prompt, $ prompt)
117	        .skip_while(|line| line.is_empty() || line.starts_with('%') || line.starts_with('$'))
118	        // Stop at trailing zsh prompt
119	        .take_while(|line| !line.starts_with('%'))
120	        .collect::<Vec<_>>()
121	        .join("\n")
122	}
123	
124	/// Assert that PTY output never contains "suspended" — the smoking gun
125	/// for the process group bug. Zsh prints "suspended (tty output)" or
126	/// "suspended (tty input)" when a background process tries terminal I/O.
127	fn assert_not_suspended(output: &str, context: &str) {
128	    let lower = strip_ansi(output).to_lowercase();
129	    assert!(
130	        !lower.contains("suspended"),
131	        "{context}: bivvy was suspended by zsh!\nOutput:\n{output}"
132	    );
133	}
134	
135	// ── Low-level PTY primitives ───────────────────────────────────────
136	//
137	// Two safe abstractions over libc that contain all the `unsafe` for
138	// poll-based PTY interaction.
139	
140	/// Write bytes to a PTY session's master file descriptor.
141	fn pty_write(session: &Session, data: &[u8]) {
142	    use std::os::unix::io::AsRawFd;
143	    let fd = session.get_stream().as_raw_fd();
144	    // SAFETY: fd is a valid, open PTY master fd obtained from the Session.
145	    // data is a valid byte slice that outlives the call.  For the short
146	    // payloads used in interactive testing (single keys, escape sequences,
147	    // short lines), partial writes are not a concern.
148	    unsafe {
149	        libc::write(fd, data.as_ptr() as *const _, data.len());
150	    }
151	}
152	
153	/// Poll for available data on a PTY fd and drain it into `accumulated`.
154	///
155	/// Temporarily sets `O_NONBLOCK` to drain all buffered data without
156	/// blocking, then restores the original flags.  Returns `true` if the
157	/// poll indicated data was ready.
158	fn poll_and_drain(
159	    fd: std::os::unix::io::RawFd,
160	    accumulated: &mut String,
161	    poll_timeout_ms: i32,
162	) -> bool {
163	    // SAFETY: poll() with a single stack-allocated pollfd is a standard
164	    // POSIX syscall.  The pollfd is valid for the duration of the call.
165	    let ready = unsafe {
166	        let mut pfd = libc::pollfd {
167	            fd,
168	            events: libc::POLLIN,
169	            revents: 0,
170	        };
171	        libc::poll(&mut pfd, 1, poll_timeout_ms)
172	    };
173	
174	    if ready > 0 {
175	        let mut buf = [0u8; 4096];
176	        // SAFETY: fcntl F_GETFL/F_SETFL and read() are standard POSIX
177	        // calls on a valid PTY fd.  O_NONBLOCK is set temporarily to
178	        // drain all available data, then the original flags are restored.
179	        // The buffer is stack-allocated and valid for each read() call.
180	        unsafe {
181	            let flags = libc::fcntl(fd, libc::F_GETFL);
182	            libc::fcntl(fd, libc::F_SETFL, flags | libc::O_NONBLOCK);
183	            loop {
184	                let n = libc::read(fd, buf.as_mut_ptr() as *mut _, buf.len());
185	                if n <= 0 {
186	                    break;
187	                }
188	                let chunk = String::from_utf8_lossy(&buf[..n as usize]);
189	                accumulated.push_str(&chunk);
190	            }
191	            libc::fcntl(fd, libc::F_SETFL, flags & !libc::O_NONBLOCK);
192	        }
193	        true
194	    } else {
195	        false
196	    }
197	}
198	
199	// ── PTY interaction helpers ─────────────────────────────────────────
200	
201	/// Poll-based wait for a pattern in PTY output. Returns the full
202	/// accumulated output (ANSI-stripped) since this call started.
203	fn wait_for(session: &Session, pattern: &str, context: &str) -> String {
204	    use std::os::unix::io::AsRawFd;
205	    use std::time::Instant;
206	
207	    let fd = session.get_stream().as_raw_fd();
208	    let mut accumulated = String::new();
209	    let start = Instant::now();
210	
211	    loop {
212	        if start.elapsed() > TIMEOUT {
213	            let clean = strip_ansi(&accumulated);
214	            panic!(
215	                "{context}\n\
216	                 Expected: {pattern:?}\n\
217	                 Timed out after {TIMEOUT:?}\n\
218	                 Accumulated PTY output (ANSI stripped):\n\
219	                 ---\n{clean}\n---"
220	            );
221	        }
222	
223	        poll_and_drain(fd, &mut accumulated, 200);
224	
225	        if strip_ansi(&accumulated).contains(pattern) {
226	            return strip_ansi(&accumulated);
227	        }
228	    }
229	}
230	
231	/// Wait for a pattern, then send a single key. Returns accumulated output.
232	#[allow(dead_code)]
233	fn wait_and_send(session: &Session, pattern: &str, key: u8, context: &str) -> String {
234	    let output = wait_for(session, pattern, context);
235	    send_key(session, key);
236	    output
237	}
238	
239	/// Send a single byte to the PTY.
240	fn send_key(session: &Session, key: u8) {
241	    pty_write(session, &[key]);
242	}
243	
244	/// Send a byte sequence to the PTY.
245	fn send_bytes(session: &Session, bytes: &[u8]) {
246	    pty_write(session, bytes);
247	}
248	
249	/// Send a command string to the PTY (with trailing newline).
250	fn send_line(session: &Session, line: &str) {
251	    let payload = format!("{line}\n");
252	    pty_write(session, payload.as_bytes());
253	}
254	
255	/// Assert the exit code of the last command run in zsh.
256	///
257	/// Uses printf with `%s` expansion so the expanded output differs from
258	/// the echoed command text (which shows `"$?"` literally, not expanded).
259	fn assert_zsh_exit_code(session: &Session, expected: i32, context: &str) {
260	    let nonce = std::time::SystemTime::now()
261	        .duration_since(std::time::UNIX_EPOCH)
262	        .unwrap()
263	        .as_nanos();
264	    let tag = format!("RC_{nonce}_");
265	    send_line(session, &format!("printf '{tag}%s\\n' \"$?\""));
266	
267	    let expected_str = format!("{tag}{expected}");
268	    let output = wait_for(session, &expected_str, &format!("{context} — exit code"));
269	    assert!(
270	        output.contains(&expected_str),
271	        "{context}: Expected exit code {expected}.\nOutput: {output}"
272	    );
273	}
274	
275	/// `y` — single key selects "Yes" in bivvy's raw-mode prompts (no Enter)
276	#[allow(dead_code)]
277	const KEY_Y: u8 = b'y';
278	
279	/// Arrow down — ANSI escape sequence (3 bytes)
280	const ARROW_DOWN: &[u8] = b"\x1b[B";
281	
282	/// Enter / carriage return
283	const KEY_ENTER: u8 = b'\r';
284	
285	// ── Project setup ───────────────────────────────────────────────────
286	
287	fn setup_project(config: &str) -> TempDir {
288	    let temp = TempDir::new().unwrap();
