290	    let bivvy_dir = temp.path().join(".bivvy");
291	    fs::create_dir_all(&bivvy_dir).unwrap();
292	    fs::write(bivvy_dir.join("config.yml"), config).unwrap();
293	
294	    let home = temp.path().join(".test_home");
