328	fn spawn_zsh(project_dir: &std::path::Path) -> Session {
329	    let home = project_dir.join(".test_home");
330	
331	    let zdotdir = home.join(".zsh_test");
332	    fs::create_dir_all(&zdotdir).unwrap();
333	
334	    fs::write(
335	        zdotdir.join(".zshrc"),
336	        format!("setopt MONITOR\nPS1='$ '\necho {READY}\n"),
337	    )
338	    .unwrap();
339	
340	    let bivvy_bin = cargo_bin("bivvy");
341	
342	    let mut cmd = Command::new("/bin/zsh");
343	    cmd.arg("-i");
344	    cmd.current_dir(project_dir);
345	    cmd.env("HOME", &home);
346	    cmd.env("ZDOTDIR", &zdotdir);
347	    cmd.env("BIVVY", &bivvy_bin);
348	    cmd.env("TERM", "dumb");
349	    cmd.env("XDG_CONFIG_HOME", home.join(".config"));
350	    cmd.env("XDG_DATA_HOME", home.join(".local/share"));
351	    cmd.env("XDG_CACHE_HOME", home.join(".cache"));
352	    cmd.env("XDG_STATE_HOME", home.join(".local/state"));
353	
354	    let mut session = Session::spawn(cmd).expect("Failed to spawn zsh");
355	    session.set_expect_timeout(Some(TIMEOUT));
