457	/// Core regression test: multi-step workflow under zsh job control.
458	/// Steps auto-run without prompts under the decision engine.
459	///
460	/// If process group handling is broken, step execution hangs and the
461	/// test times out — or zsh reports "suspended (tty output)".
462	#[test]
463	fn interactive_workflow_under_zsh_job_control() {
464	    let temp = setup_project(INTERACTIVE_CONFIG);
465	    let session = spawn_zsh(temp.path());
466	
467	    wait_for(&session, READY, "Waiting for zsh to start");
468	    send_line(&session, "$BIVVY run");
469	
470	    // All 3 steps auto-run without prompts. Wait for workflow completion.
471	    let summary = wait_for(&session, "bivvy status", "Workflow completion");
472	    assert_not_suspended(&summary, "interactive workflow");
473	    insta::assert_snapshot!(
474	        "interactive_workflow_summary",
475	        normalize_for_snapshot(&summary)
476	    );
477	
478	    assert_zsh_exit_code(&session, 0, "interactive workflow");
479	
480	    assert!(
481	        temp.path().join(".step1.txt").exists(),
482	        "Step 1 side-effect missing"
483	    );
484	    assert!(
485	        temp.path().join(".step2.txt").exists(),
486	        "Step 2 side-effect missing"
487	    );
488	    assert!(
489	        temp.path().join(".step3.txt").exists(),
490	        "Step 3 side-effect missing"
491	    );
492	
493	    send_line(&session, "exit");
494	}
