564	/// A failing step under zsh job control. Step 1 auto-runs,
565	/// step 2 fails and shows the recovery menu. We navigate to "Abort"
566	/// via arrow keys and Enter.
567	#[test]
568	fn failed_step_under_zsh_job_control() {
569	    let temp = setup_project(FAILING_CONFIG);
570	    let session = spawn_zsh(temp.path());
571	
572	    wait_for(&session, READY, "Waiting for zsh to start");
573	    send_line(&session, "$BIVVY run");
574	
575	    // Step 1: auto-runs (no prompt). Step 2: auto-runs, fails.
576	    // Recovery menu: Retry / Skip / Shell / Abort.
577	    // Navigate to Abort: 3x arrow-down, then Enter.
578	    //
579	    // TERM=dumb routes through prompt_select_dumb (bypasses dialoguer
580	    // entirely). Options are printed once with no redraw cycle. Arrow
581	    // keys are parsed by console::Term::read_key() in raw mode — ANSI
582	    // escape parsing is hardcoded, not terminfo-dependent, so arrow
583	    // navigation works regardless of TERM value. Internal selection
584	    // state updates silently (no visual feedback on dumb terminals).
585	    //
586	    // Wait for the last option ("Abort") to confirm all options rendered
587	    // and raw mode is active before sending arrow keys.
588	    wait_for(&session, "Abort", "Recovery menu options");
589	    for _ in 0..3 {
590	        send_bytes(&session, ARROW_DOWN);
591	    }
592	    send_key(&session, KEY_ENTER);
593	
594	    // Wait for the closing box line to ensure full summary is captured
595	    let summary = wait_for(
596	        &session,
597	        "\u{2514}\u{2500}\u{2500}\u{2500}", // └───
598	        "Workflow summary after abort",
599	    );
600	    assert_not_suspended(&summary, "failed step workflow");
601	    insta::assert_snapshot!(
602	        "failed_step_workflow_summary",
603	        normalize_for_snapshot(&summary)
604	    );
605	
606	    assert_zsh_exit_code(&session, 1, "failing workflow");
607	
608	    assert!(
609	        temp.path().join(".succeeded.txt").exists(),
610	        "Step 1 should have run"
611	    );
612	    assert!(
613	        !temp.path().join(".after-fail.txt").exists(),
614	        "Step 3 should NOT have run (blocked)"
615	    );
616	
617	    // Zsh must still be responsive after bivvy failure
618	    let nonce = std::time::SystemTime::now()
619	        .duration_since(std::time::UNIX_EPOCH)
620	        .unwrap()
621	        .as_nanos();
622	    let alive_tag = format!("ALIVE_{nonce}");
623	    send_line(&session, &format!("printf '{alive_tag}\\n'"));
624	    wait_for(&session, &alive_tag, "Zsh responsive after failure");
625	
626	    send_line(&session, "exit");
627	}
