1	//! Initialization screen with detection and step template selection.
2	//!
3	//! This screen displays detected technologies and provides a selectable
4	//! list of suggested step templates based on the detection results.
5	//!
6	//! ## Bivvy Components Used
7	//!
8	//! - `HeaderWidget` — Branding, progress steps (center), action buttons (right)
9	//! - `ProgressSteps` — Step indicator built into the header center
10	//! - `ChipGroup` — Display detected technologies as chips
11	//! - `CardList` — Selectable step templates with checkbox indicators
12	//! - `SectionCard` — Bordered sections for DETECTED, SUGGESTED STEPS, SUMMARY
13	//! - `FooterWidget` — Keyboard hints from BindingSet
14	//! - `Button` — Action bar confirm/cancel buttons (in header)
15	//!
16	//! ## Interaction Compliance
17	//!
18	//! - Screens handle semantic `Action`s, never raw key events
19	//! - `bindings()` returns the active `BindingSet` for key resolution & footer
20	//! - `render()` registers `HitRegion`s in the `HitMap` for mouse click targets
21	//! - `handle_click()` implements FocusThenFire for the step template list
22	//!
23	//! ## Layout
24	//!
25	//! Uses `screen_layouts::init()` + `allocate_regions()`:
26	//! ```text
27	//! ┌────────────────────────────────────────┐
28	//! │ Header — branding+progress+btns Pin(3) │
29	//! ├────────────────────────────────────────┤
30	//! │ Detection — chips (Flex 5/3)           │
31	//! ├────────────────────────────────────────┤
32	//! │ Steps — selection list (Flex 14/5)     │
33	//! ├────────────────────────────────────────┤
34	//! │ Summary (Flex 4/2)                     │
35	//! ├────────────────────────────────────────┤
36	//! │ Footer (Pin 2)                         │
37	//! └────────────────────────────────────────┘
38	//! ```
39	
40	use std::cell::Cell;
41	
42	use ratatui::prelude::*;
43	
44	use crate::ui::tui::app::AppState;
45	use ratatui::widgets::{Block, Borders, Clear};
46	
47	use crate::ui::tui::components::{
48	    Button, ButtonColor, CardList, CardListItem, CardListSpacing, ChipGroup, ChipGroupItem,
49	    FooterWidget, HeaderData, HeaderWidget, ProgressSteps, SectionCard,
50	};
51	use crate::ui::tui::interaction::{bindings, Action, BindingSet, ClickBehavior, HitMap, HitRegion};
52	use crate::ui::tui::layouts::screen_layouts;
53	use crate::ui::tui::layouts::{allocate_regions, DegradeMode};
54	use crate::ui::tui::screen::{KeyHint, Screen, ScreenResult};
55	use crate::ui::tui::theme::{Palette, Theme};
56	
57	/// Progress step in the init flow.
58	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
59	pub enum ProgressStep {
60	    Detect,
61	    Configure,
62	    Confirm,
63	}
64	
65	impl ProgressStep {
66	    fn all() -> [ProgressStep; 3] {
67	        [
68	            ProgressStep::Detect,
69	            ProgressStep::Configure,
70	            ProgressStep::Confirm,
71	        ]
72	    }
73	
74	    fn label(&self) -> &'static str {
75	        match self {
76	            ProgressStep::Detect => "Detect",
77	            ProgressStep::Configure => "Configure",
78	            ProgressStep::Confirm => "Confirm",
79	        }
80	    }
81	
82	    fn index(&self) -> usize {
83	        match self {
84	            ProgressStep::Detect => 0,
85	            ProgressStep::Configure => 1,
86	            ProgressStep::Confirm => 2,
87	        }
88	    }
89	}
90	
91	/// A detected technology.
92	#[derive(Debug, Clone)]
93	pub struct DetectionResult {
94	    /// Name of the detected technology (e.g., "Rust", "Node").
95	    pub name: String,
96	    /// Additional detail (e.g., "Cargo.toml", "package.json").
97	    pub detail: Option<String>,
98	    /// Whether the technology was found.
99	    pub found: bool,
100	}
101	
102	impl DetectionResult {
103	    /// Create a new detection result for a found technology.
104	    pub fn new(name: impl Into<String>, detail: impl Into<String>) -> Self {
105	        Self {
106	            name: name.into(),
107	            detail: Some(detail.into()),
108	            found: true,
109	        }
110	    }
111	
112	    /// Create a detection result for a technology that was not found.
113	    pub fn not_found(name: impl Into<String>) -> Self {
114	        Self {
115	            name: name.into(),
116	            detail: None,
117	            found: false,
118	        }
119	    }
120	}
121	
122	/// A suggested step template detected for the project.
123	#[derive(Debug, Clone)]
124	pub struct StepTemplate {
125	    /// Name of the step template (e.g., "brew", "mise", "cargo").
126	    pub name: String,
127	    /// Why this template is suggested (e.g., "Detected Cargo.toml").
128	    pub reason: String,
129	    /// Whether this step is selected for inclusion.
130	    pub selected: bool,
131	}
132	
133	impl StepTemplate {
134	    /// Create a new step template option.
135	    pub fn new(name: impl Into<String>, reason: impl Into<String>) -> Self {
136	        Self {
137	            name: name.into(),
138	            reason: reason.into(),
139	            selected: false,
140	        }
141	    }
142	
143	    /// Create a new step template option that is pre-selected.
144	    pub fn new_selected(name: impl Into<String>, reason: impl Into<String>) -> Self {
145	        Self {
146	            name: name.into(),
147	            reason: reason.into(),
148	            selected: true,
149	        }
150	    }
151	}
152	
153	/// Result of the init screen interaction.
154	#[derive(Debug, Clone)]
155	pub enum InitResult {
156	    /// User confirmed selections.
157	    Confirmed(Vec<String>),
158	    /// User cancelled.
159	    Cancelled,
160	}
161	
162	/// The init screen.
163	pub struct InitScreen {
164	    /// Detected technologies.
165	    detections: Vec<DetectionResult>,
166	    /// Suggested step templates.
167	    step_templates: Vec<StepTemplate>,
168	    /// Currently focused step template index.
169	    pub selected_index: usize,
170	    /// Scroll offset for the template list (first visible item index).
171	    scroll_offset: usize,
172	    /// Number of visible items (updated during render via interior mutability).
173	    visible_count: Cell<usize>,
174	    /// Current progress step.
175	    current_step: ProgressStep,
176	    /// Project name (for header).
177	    project_name: String,
178	    /// Whether the user has confirmed.
179	    completed: bool,
180	    /// Whether the user cancelled.
181	    cancelled: bool,
182	    /// Whether the help overlay is showing.
183	    show_help: bool,
184	    /// Theme for styling.
185	    theme: Theme,
186	}
187	
188	impl InitScreen {
189	    pub fn new() -> Self {
190	        Self {
191	            detections: Vec::new(),
192	            step_templates: Vec::new(),
193	            selected_index: 0,
194	            scroll_offset: 0,
195	            visible_count: Cell::new(0),
196	            current_step: ProgressStep::Configure,
197	            project_name: "my-project".to_string(),
198	            completed: false,
199	            cancelled: false,
200	            show_help: false,
201	            theme: Theme::default(),
202	        }
203	    }
204	
205	    /// Set the project name.
206	    pub fn project_name(mut self, name: impl Into<String>) -> Self {
207	        self.project_name = name.into();
208	        self
209	    }
210	
211	    /// Set the current progress step.
212	    pub fn current_step(mut self, step: ProgressStep) -> Self {
213	        self.current_step = step;
214	        self
215	    }
216	
217	    pub fn add_detection(&mut self, result: DetectionResult) {
218	        self.detections.push(result);
219	    }
220	
221	    pub fn add_step_template(&mut self, template: StepTemplate) {
222	        self.step_templates.push(template);
223	    }
224	
225	    /// Deprecated: Use add_step_template instead.
226	    pub fn add_workflow(&mut self, option: StepTemplate) {
227	        self.step_templates.push(option);
228	    }
229	
230	    pub fn move_selection(&mut self, delta: i32) {
231	        let new_index = self.selected_index as i32 + delta;
232	        if new_index >= 0 && (new_index as usize) < self.step_templates.len() {
233	            self.selected_index = new_index as usize;
234	            self.ensure_visible();
235	        }
236	    }
237	
238	    /// Adjust scroll_offset to ensure selected_index is visible.
239	    fn ensure_visible(&mut self) {
240	        let visible = self.visible_count.get();
241	        if visible == 0 {
242	            return;
243	        }
244	
245	        // If selected is above visible area, scroll up
246	        if self.selected_index < self.scroll_offset {
247	            self.scroll_offset = self.selected_index;
248	        }
249	
250	        // If selected is below visible area, scroll down
251	        let last_visible = self.scroll_offset + visible.saturating_sub(1);
252	        if self.selected_index > last_visible {
253	            self.scroll_offset = self.selected_index.saturating_sub(visible - 1);
254	        }
255	    }
256	
257	    pub fn toggle_selection(&mut self) {
258	        // Multi-select behavior: toggle the current item
259	        if let Some(template) = self.step_templates.get_mut(self.selected_index) {
260	            template.selected = !template.selected;
261	        }
262	    }
263	
264	    pub fn get_selected_steps(&self) -> Vec<String> {
265	        self.step_templates
266	            .iter()
267	            .filter(|t| t.selected)
268	            .map(|t| t.name.clone())
269	            .collect()
270	    }
