402	    fn render_detections(&self, frame: &mut Frame, area: Rect, mode: DegradeMode) {
403	        let found: Vec<_> = self.detections.iter().filter(|d| d.found).collect();
404	
405	        // Create card with title — DegradeMode flows through from allocator
406	        let card = SectionCard::new().title("DETECTED").degrade_mode(mode);
407	        let inner = card.render(frame, area);
408	
409	        if inner.height == 0 {
410	            return;
411	        }
412	
413	        // Render count badge in top-right of card (only when Full mode has a border)
414	        if mode == DegradeMode::Full && inner.height > 0 {
415	            let count = format!("{} items", found.len());
416	            let badge_x = inner.x + inner.width - count.len() as u16 - 1;
417	            frame.buffer_mut().set_string(
418	                badge_x,
419	                area.y, // In the border row
420	                &count,
421	                Style::default().fg(Palette::TEAL),
422	            );
423	        }
424	
425	        if found.is_empty() {
426	            let empty = Line::styled(
427	                "No technologies detected",
428	                Style::default().fg(Palette::TEXT_DIM),
429	            );
430	            frame
431	                .buffer_mut()
432	                .set_line(inner.x, inner.y, &empty, inner.width);
433	            return;
434	        }
435	
436	        // Create chip group items
437	        let chip_items: Vec<ChipGroupItem> = found
438	            .iter()
439	            .map(|d| ChipGroupItem::new(&d.name, d.detail.as_deref()))
440	            .collect();
441	
442	        let chip_group = ChipGroup::new(chip_items).degrade_mode(mode);
443	        chip_group.render(frame, inner);
444	
445	        // Render "Based on:" line if we have space
446	        if inner.height >= 4 {
447	            let details: Vec<_> = found.iter().filter_map(|d| d.detail.as_deref()).collect();
448	
449	            if !details.is_empty() {
450	                let based_on = format!("Based on: {}", details.join(", "));
451	                let y = inner.y + inner.height - 1;
452	
453	                // Draw subtle separator
454	                for x in inner.x..inner.x + inner.width {
455	                    if let Some(cell) = frame
456	                        .buffer_mut()
457	                        .cell_mut(Position::new(x, y.saturating_sub(1)))
458	                    {
459	                        cell.set_style(Style::default().fg(Palette::BORDER_SUBTLE));
460	                    }
461	                }
462	
463	                frame.buffer_mut().set_string(
464	                    inner.x,
465	                    y,
466	                    &based_on,
467	                    Style::default().fg(Palette::TEXT_DIM),
468	                );
469	            }
470	        }
471	    }
