        if let Some(h) = hint {
            eprintln!();
            eprintln!("{}Hint: {}", pad, h);
        }
    }
}

impl Prompter for NonInteractiveStepDisplay {
    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
        // Non-interactive: reuse env override or default logic.
