1	//! Init command implementation.
2	//!
3	//! The `bivvy init` command initializes project configuration.
4	
5	use std::fs;
6	use std::path::{Path, PathBuf};
7	
8	use crate::cli::args::{InitArgs, RunArgs};
9	use crate::detection::DetectionRunner;
10	use crate::error::Result;
11	use crate::registry::builtin::BuiltinLoader;
12	use crate::registry::template::Template;
13	use crate::ui::{
14	    hints, OutputWriter, Prompt, PromptOption, PromptResult, PromptType, UserInterface,
15	};
16	
17	use super::dispatcher::{Command, CommandResult};
18	use super::run::RunCommand;
19	
20	/// The init command implementation.
21	pub struct InitCommand {
22	    project_root: PathBuf,
23	    args: InitArgs,
24	}
25	
26	impl InitCommand {
27	    /// Create a new init command.
28	    pub fn new(project_root: &Path, args: InitArgs) -> Self {
29	        Self {
30	            project_root: project_root.to_path_buf(),
31	            args,
32	        }
33	    }
34	
35	    /// Get the project root path.
36	    pub fn project_root(&self) -> &Path {
37	        &self.project_root
38	    }
39	
40	    /// Get the command arguments.
41	    pub fn args(&self) -> &InitArgs {
42	        &self.args
43	    }
44	
45	    /// Check if config already exists.
46	    fn config_exists(&self) -> bool {
47	        self.project_root.join(".bivvy/config.yml").exists()
48	    }
49	
50	    /// Resolve the absolute path to the user's local schema file.
51	    ///
52	    /// Returns `~/.bivvy/schema.json` if the home directory is discoverable.
53	    /// `main` runs `ensure_global_config()` before any command dispatches,
54	    /// so this file is guaranteed to exist by the time `init` is invoked.
55	    fn schema_path() -> Option<PathBuf> {
56	        crate::sys::home_dir().map(|h| h.join(".bivvy/schema.json"))
57	    }
58	
59	    /// Create configuration content from selected steps with template info.
60	    ///
61	    /// When `schema_path` is `Some`, prepends a `# yaml-language-server:`
62	    /// directive so editors with the YAML language server pick up completion
63	    /// and validation against the locally installed schema.
64	    fn create_config(
65	        &self,
66	        steps: &[(&str, Option<&Template>)],
67	        schema_path: Option<&Path>,
68	    ) -> String {
69	        let project_name = self
70	            .project_root
71	            .file_name()
72	            .and_then(|n| n.to_str())
73	            .unwrap_or("MyApp");
74	
75	        let mut config = String::new();
76	
77	        if let Some(path) = schema_path {
78	            config.push_str(&format!(
79	                "# yaml-language-server: $schema={}\n",
80	                path.display()
81	            ));
82	        }
83	
84	        config.push_str(&format!(
85	            "# Bivvy configuration for {project_name}\n\
86	             # Docs: https://bivvy.dev/configuration\n\
87	             #\n\
88	             # Override any template field per-step:\n\
89	             #   steps:\n\
90	             #     example:\n\
91	             #       template: bundle-install\n\
92	             #       env:\n\
93	             #         BUNDLE_WITHOUT: \"production\"\n\
94	             #\n\
95	             # Add custom steps:\n\
96	             #   steps:\n\
97	             #     setup_db:\n\
98	             #       title: \"Set up database\"\n\
99	             #       command: \"bin/rails db:setup\"\n\
100	             #       check:\n\
101	             #         type: execution\n\
102	             #         command: \"bin/rails db:version\"\n\
103	             #\n\
104	             # Create named workflows:\n\
105	             #   workflows:\n\
106	             #     ci:\n\
107	             #       steps: [bundle-install, yarn-install]\n\
108	             #       settings:\n\
109	             #         defaults:\n\
110	             #           output: quiet\n\
111	             \n\
112	             app_name: \"{project_name}\"\n\
113	             \n\
114	             settings:\n\
115	             \x20 defaults:\n\
116	             \x20   output: verbose  # verbose | quiet | silent\n"
117	        ));
118	
119	        if !steps.is_empty() {
120	            config.push_str("\nsteps:\n");
121	
122	            let step_names: Vec<&str> = steps.iter().map(|(name, _)| *name).collect();
123	
124	            for (name, template) in steps {
125	                config.push_str(&format!("  {}:\n    template: {}\n", name, name));
126	
127	                if let Some(tmpl) = template {
128	                    // Show command
129	                    if let Some(ref cmd) = tmpl.step.command {
130	                        config.push_str(&format!("    # command: {}\n", cmd));
131	                    }
132	
133	                    // Template details are shown as command comment above
134	                }
135	
136	                config.push('\n');
137	            }
138	
139	            config.push_str("workflows:\n  default:\n    steps: ");
140	            config.push_str(&format!("[{}]\n", step_names.join(", ")));
141	        }
142	
143	        config
144	    }
145	
146	    /// Execute `--from`: copy config from another project.
147	    ///
148	    /// Only requires `OutputWriter` — displays messages but does not prompt.
149	    fn execute_from(&self, ui: &mut dyn OutputWriter, from_path: &str) -> Result<CommandResult> {
150	        let source = Path::new(from_path).join(".bivvy/config.yml");
151	        if !source.exists() {
152	            ui.error(&format!(
153	                "No .bivvy/config.yml found at {}",
154	                source.display()
155	            ));
156	            return Ok(CommandResult::failure(1));
157	        }
158	
159	        let bivvy_dir = self.project_root.join(".bivvy");
160	        fs::create_dir_all(&bivvy_dir)?;
161	        fs::copy(&source, bivvy_dir.join("config.yml"))?;
162	
163	        self.update_gitignore(ui)?;
164	
165	        ui.message("");
166	        ui.success(&format!("Copied configuration from {}", source.display()));
167	
168	        ui.show_hint(hints::after_init());
169	        Ok(CommandResult::success())
170	    }
171	
172	    /// Execute `--template`: generate config from a specific template or category.
173	    fn execute_template(
174	        &self,
175	        ui: &mut dyn UserInterface,
176	        template_name: &str,
177	    ) -> Result<CommandResult> {
178	        let loader = match BuiltinLoader::new() {
179	            Ok(l) => l,
180	            Err(e) => {
181	                ui.error(&format!("Failed to load templates: {}", e));
182	                return Ok(CommandResult::failure(1));
183	            }
184	        };
185	
186	        // Collect matching templates: first try as a direct template name,
187	        // then try as a category name to find all templates in that category.
188	        let mut steps: Vec<(String, Option<&Template>)> = Vec::new();
189	
190	        if let Some(tmpl) = loader.get(template_name) {
191	            // Direct template match
192	            steps.push((tmpl.name.clone(), Some(tmpl)));
193	        } else {
194	            // Try as a category — find all templates in this category
195	            for qualified_name in loader.template_names() {
196	                if let Some(tmpl) = loader.get(qualified_name) {
197	                    if tmpl.category == template_name {
198	                        steps.push((tmpl.name.clone(), Some(tmpl)));
199	                    }
200	                }
201	            }
202	        }
203	
204	        if steps.is_empty() {
205	            ui.error(&format!(
206	                "No template or category found matching '{}'",
207	                template_name
208	            ));
209	            ui.message("Run 'bivvy templates' to see available templates.");
210	            return Ok(CommandResult::failure(1));
211	        }
212	
213	        ui.message(&format!("Using template: {}", template_name));
214	
215	        let steps_with_templates: Vec<(&str, Option<&Template>)> = steps
216	            .iter()
217	            .map(|(name, tmpl)| (name.as_str(), *tmpl))
218	            .collect();
219	
220	        let schema = Self::schema_path();
221	        let config = self.create_config(&steps_with_templates, schema.as_deref());
222	
223	        let bivvy_dir = self.project_root.join(".bivvy");
224	        fs::create_dir_all(&bivvy_dir)?;
225	        fs::write(bivvy_dir.join("config.yml"), &config)?;
226	
227	        self.update_gitignore(ui)?;
228	
229	        ui.message("");
230	        ui.success("Created .bivvy/config.yml");
231	
232	        let step_names: Vec<&str> = steps.iter().map(|(n, _)| n.as_str()).collect();
233	        ui.message("Workflow: default");
234	        ui.message(&format!(
235	            "Steps: {} ({})",
236	            steps.len(),
237	            step_names.join(", ")
238	        ));
239	        ui.message("");
240	
241	        ui.show_hint(hints::after_init());
242	        Ok(CommandResult::success())
243	    }
244	
245	    /// Update gitignore to exclude local overrides.
246	    ///
247	    /// Only requires `OutputWriter` — displays a message but does not prompt.
248	    fn update_gitignore(&self, ui: &mut dyn OutputWriter) -> Result<()> {
249	        let entries = [".bivvy/config.local.yml"];
250	        let gitignore_path = self.project_root.join(".gitignore");
251	
252	        if gitignore_path.exists() {
253	            let content = fs::read_to_string(&gitignore_path)?;
254	            let mut new_content = content.clone();
255	
256	            for entry in &entries {
257	                if !new_content.contains(entry) {
258	                    if !new_content.ends_with('\n') {
259	                        new_content.push('\n');
260	                    }
261	                    new_content.push_str(entry);
262	                    new_content.push('\n');
263	                    ui.message(&format!("Added {} to .gitignore", entry));
264	                }
265	            }
266	
267	            if new_content != content {
268	                fs::write(&gitignore_path, new_content)?;
269	            }
270	        }
271	
272	        Ok(())
273	    }
274	}
275	
276	impl Command for InitCommand {
277	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
278	        // Check if config already exists
279	        if self.config_exists() && !self.args.force {
280	            ui.warning("Configuration already exists. Use --force to overwrite.");
281	            return Ok(CommandResult::failure(1));
282	        }
283	
284	        // Show init header with version
285	        let version = crate::updates::version::VERSION;
286	        ui.message(&format!(
287	            "\n{} {} {}\n",
288	            console::style("⛺").bold().magenta(),
289	            console::style(format!("bivvy v{}", version)).dim(),
290	            console::style("· init").dim(),
291	        ));
292	
293	        // Handle --from: copy config from another project
294	        if let Some(ref from_path) = self.args.from {
295	            return self.execute_from(ui, from_path);
296	        }
297	
298	        // Handle --template: use a specific template instead of detection
299	        if let Some(ref template_name) = self.args.template {
300	            return self.execute_template(ui, template_name);
301	        }
302	
303	        // Run detection
304	        let detection = DetectionRunner::run(&self.project_root);
305	
306	        // Show detected technologies
307	        if !detection.project.details.is_empty() {
308	            ui.message("Detected technologies:");
309	            for detail in &detection.project.details {
310	                ui.success(&format!("{} - {}", detail.name, detail.details.join(", ")));
311	            }
312	            ui.message("");
313	        }
314	
315	        // Show conflicts
316	        for conflict in &detection.conflicts {
317	            ui.warning(&conflict.message);
318	            ui.message(&format!("  Suggestion: {}", conflict.suggestion));
319	            ui.message("");
320	        }
321	
322	        // Collect steps to include
323	        let mut steps = Vec::new();
324	
325	        if self.args.minimal || !ui.is_interactive() {
326	            // Just use detected templates
327	            for suggestion in &detection.suggested_templates {
328	                steps.push(suggestion.name.to_string());
329	            }
330	        } else if !detection.suggested_templates.is_empty() {
331	            // Interactive multi-select checklist
332	            let options: Vec<PromptOption> = detection
333	                .suggested_templates
334	                .iter()
335	                .map(|s| PromptOption {
336	                    label: format!("{} — {}", s.name, s.reason),
337	                    value: s.name.to_string(),
338	                })
339	                .collect();
340	
341	            let all_values = detection
342	                .suggested_templates
343	                .iter()
344	                .map(|s| s.name.as_str())
345	                .collect::<Vec<_>>()
346	                .join(",");
347	
348	            let prompt = Prompt {
349	                key: "init_steps".to_string(),
350	                question: "Select steps to include".to_string(),
351	                prompt_type: PromptType::MultiSelect { options },
352	                default: Some(all_values),
353	            };
354	
355	            if let Ok(PromptResult::Strings(selected)) = ui.prompt(&prompt) {
356	                steps = selected;
357	            }
358	        }
359	
360	        // Load templates to enrich config output
361	        let loader = BuiltinLoader::new().ok();
362	        let steps_with_templates: Vec<(&str, Option<&Template>)> = steps
363	            .iter()
364	            .map(|name| {
365	                let template = loader.as_ref().and_then(|l| l.get(name));
366	                (name.as_str(), template)
367	            })
368	            .collect();
369	
370	        // Generate config
371	        let schema = Self::schema_path();
372	        let config = self.create_config(&steps_with_templates, schema.as_deref());
373	
374	        // Write config
375	        let bivvy_dir = self.project_root.join(".bivvy");
376	        fs::create_dir_all(&bivvy_dir)?;
377	        fs::write(bivvy_dir.join("config.yml"), &config)?;
378	
379	        // Update gitignore
380	        self.update_gitignore(ui)?;
381	
382	        ui.message("");
383	        ui.success("Created .bivvy/config.yml");
384	
385	        // Show init summary
386	        let step_names: Vec<&str> = steps.iter().map(|s| s.as_str()).collect();
387	        ui.message("Workflow: default");
388	        ui.message(&format!(
389	            "Steps: {} ({})",
390	            steps.len(),
391	            step_names.join(", ")
392	        ));
393	        ui.message("");
394	
395	        // Offer to run setup immediately (interactive only)
396	        if ui.is_interactive() {
397	            let prompt = Prompt {
398	                key: "run_after_init".to_string(),
399	                question: "Run setup now?".to_string(),
400	                prompt_type: PromptType::Select {
401	                    options: vec![
402	                        PromptOption {
403	                            label: "No  (n)".to_string(),
404	                            value: "no".to_string(),
405	                        },
406	                        PromptOption {
407	                            label: "Yes (y)".to_string(),
408	                            value: "yes".to_string(),
409	                        },
410	                    ],
411	                },
412	                default: Some("no".to_string()),
413	            };
414	
415	            if let Ok(PromptResult::String(answer)) = ui.prompt(&prompt) {
416	                if answer == "yes" {
417	                    ui.message("");
418	                    let run_args = RunArgs {
419	                        force: steps.iter().map(|s| s.to_string()).collect(),
420	                        suppress_header: true,
421	                        ..RunArgs::default()
422	                    };
423	                    let run_cmd = RunCommand::new(&self.project_root, run_args);
424	                    return run_cmd.execute(ui);
425	                }
426	            }
427	        }
428	
429	        ui.show_hint(hints::after_init());
430	
431	        Ok(CommandResult::success())
432	    }
433	}
