///
/// This does not echo anything.  If the terminal is not user attended
/// the return value will always be the unknown key.
pub fn read_key(&self) -> io::Result<Key> {
    if !self.is_tty {
        Ok(Key::Unknown)
    } else {
        read_single_key(false)
    }
}

