            return; // Skip under --nocapture with real TTY
        }

        // 2-option yes/no (takes the custom prompt_yes_no path)
        let yn_options = vec![
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
        ];
        let yn_prompt = make_prompt(
            "yn",
            PromptType::Select {
                options: yn_options.clone(),
            },
