        let prompt = make_prompt(
            "test_eof",
            PromptType::Select {
                options: options.clone(),
            },
            Some("yes"),
        );

        let result = prompt_yes_no(&prompt, &options, &term);
        assert!(result.is_err(), "prompt_yes_no should error on non-TTY (EOF)");
    }

    #[test]
    fn prompt_select_dumb_returns_error_on_eof() {
